def cloud_root():
    if platform.system() != 'Linux':
        raise RuntimeError('Cloud-only policy: laptop training is disabled.')
    if os.environ.get('KAGGLE_KERNEL_RUN_TYPE') and Path('/kaggle/working').is_dir():
        return Path('/kaggle/working/pdf_reasoning_018')
    if os.environ.get('COLAB_RELEASE_TAG') and Path('/content').is_dir():
        return Path('/content/pdf_reasoning_018')
    raise RuntimeError('A hosted Kaggle or Colab runtime is required; no local override.')


def main():
    out = cloud_root()
    out.mkdir(parents=True, exist_ok=True)
    def save(name, value):
        (out/name).write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding='utf-8')
    def status(stage, **extra):
        save('status.json', dict(stage=stage, utc=datetime.now(timezone.utc).isoformat(), **extra))
        print(stage, flush=True)
    try:
        assert PAYLOAD and PAYLOAD['manifest']['model'] == 'Qwen/Qwen3-8B'
        status('cloud_preflight')
        os.environ['CUDA_VISIBLE_DEVICES'] = '0'
        os.environ['TOKENIZERS_PARALLELISM'] = 'false'
        os.environ['WANDB_DISABLED'] = 'true'
        os.environ['HF_HOME'] = '/tmp/pdf-sft-hf'
        import torch
        if not torch.cuda.is_available():
            raise RuntimeError('No working CUDA GPU. CPU training is disabled; fix cloud allocation.')
        # Check connectivity before spending time on package retries or model download.
        import urllib.request
        for url in ['https://pypi.org/simple/transformers/', 'https://huggingface.co/api/models/Qwen/Qwen3-8B']:
            with urllib.request.urlopen(url, timeout=15) as response:
                assert response.status == 200
        status('installing_dependencies')
        subprocess.run([sys.executable, '-m', 'pip', 'install', '--quiet', '--retries', '1',
                        'transformers==4.56.2', 'peft==0.17.1', 'accelerate==1.10.1',
                        'bitsandbytes==0.47.0'], check=True)
        from transformers import AutoModelForCausalLM, AutoTokenizer, BitsAndBytesConfig, Trainer, TrainingArguments, set_seed
        from peft import LoraConfig, get_peft_model, prepare_model_for_kbit_training
        from huggingface_hub import model_info
        set_seed(217)
        model_id = 'Qwen/Qwen3-8B'
        revision = PAYLOAD['manifest']['revision']
        dtype = torch.bfloat16 if torch.cuda.is_bf16_supported() else torch.float16
        save('dataset_manifest.json', PAYLOAD['manifest'])
        save('runtime.json', dict(model=model_id, revision=revision, seed=217,
            gpu=torch.cuda.get_device_name(0), cuda=torch.version.cuda,
            packages={p: importlib.metadata.version(p) for p in
                      ['torch', 'transformers', 'peft', 'accelerate', 'bitsandbytes']},
            payload_sha256=hashlib.sha256(json.dumps(PAYLOAD, sort_keys=True).encode()).hexdigest()))
        (out/'ATTRIBUTION.txt').write_text(PAYLOAD['attribution'], encoding='utf-8')
        status('loading_model')
        tokenizer = AutoTokenizer.from_pretrained(model_id, revision=revision, trust_remote_code=False)
        tokenizer.pad_token = tokenizer.eos_token
        model = AutoModelForCausalLM.from_pretrained(model_id, revision=revision,
            trust_remote_code=False, device_map={'': 0}, torch_dtype=dtype, attn_implementation='sdpa',
            quantization_config=BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type='nf4',
                bnb_4bit_use_double_quant=True, bnb_4bit_compute_dtype=dtype))
        def prompt(row, thinking=False):
            return tokenizer.apply_chat_template(row['messages'][:-1], tokenize=False,
                                                 add_generation_prompt=True, enable_thinking=thinking)
        def generate(label, thinking):
            model.eval()
            results = []
            for row in PAYLOAD['test']:
                set_seed(217)
                inputs = tokenizer(prompt(row, thinking), return_tensors='pt').to('cuda:0')
                with torch.inference_mode():
                    answer = model.generate(**inputs, do_sample=True, temperature=0.6, top_p=0.95, top_k=20, max_new_tokens=2048,
                                            use_cache=True, pad_token_id=tokenizer.pad_token_id)
                raw=tokenizer.decode(answer[0,inputs.input_ids.shape[1]:], skip_special_tokens=True)
                final=raw.split('</think>',1)[1].strip() if '</think>' in raw else ('' if thinking else raw)
                results.append(dict(thinking=thinking, final_response=final, reason_end_seen='</think>' in raw,id=row['id'], question=row['messages'][-2]['content'],
                    reference=row['messages'][-1]['content'], provenance=row['provenance'],
                    response=tokenizer.decode(answer[0,inputs.input_ids.shape[1]:], skip_special_tokens=True),
                    generated_tokens=int(answer.shape[1]-inputs.input_ids.shape[1]),
                    hit_token_limit=bool(answer.shape[1]-inputs.input_ids.shape[1]>=2048),
                    evidence_ids=row['evidence_ids']))
            save(label+'.json', results)
        status('baseline_evaluation')
        generate('baseline_non_thinking', False)
        generate('baseline_thinking', True)
        from peft import PeftModel
        candidates=list(Path('/kaggle/input').rglob('adapter/adapter_model.safetensors'))
        matching=[p for p in candidates if hashlib.sha256(p.read_bytes()).hexdigest()=='98a59cc00ae482e751915af12fee3d6d8fa942755319d91c37567e1e1fb6fd42']
        assert len(matching)==1, 'Expected exactly one verified adapter017'
        model=PeftModel.from_pretrained(model,matching[0].parent,is_trainable=False)
        generate('adapted_non_thinking', False)
        generate('adapted_thinking', True)
        save('protocol.json', dict(training_executed=False, cases=8, generations=32,
            comparison='Eight exposed development questions; base/adapter017 crossed with thinking off/on. Same sampling settings and2048 output token cap in all conditions. Single-seed diagnostic, no final acceptance. Compare within job, not greedy historical outputs.',adapter_sha256='98a59cc00ae482e751915af12fee3d6d8fa942755319d91c37567e1e1fb6fd42'))
        status('completed_diagnostic_human_review_pending',training_executed=False)
    except Exception as exc:
        status('failed', error_type=type(exc).__name__, error=str(exc),
               completed_training=False)
        (out/'failure.txt').write_text(traceback.format_exc(), encoding='utf-8')
        raise


if __name__ == '__main__':
    main()
